#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <curl/curl.h>

#define MAX_FIELD_LEN 256
#define MAX_ENCODED_LEN 1024
#define MAX_QUERY_LEN 4096
#define MAX_RETRIES 3

typedef struct {
    char *data;
    size_t len;
} response_buf_t;

static size_t write_callback(void *contents, size_t size, size_t nmemb, void *userp) {
    size_t total = size * nmemb;
    response_buf_t *buf = (response_buf_t *)userp;
    char *tmp = realloc(buf->data, buf->len + total + 1);
    if (!tmp) return 0;
    buf->data = tmp;
    memcpy(buf->data + buf->len, contents, total);
    buf->len += total;
    buf->data[buf->len] = '\0';
    return total;
}

/* Encode a field for safe embedding in a GraphQL JSON query string.
 * Handles: backslash, double-quote, and control characters.
 * Uses a two-pass approach: first pass counts needed size,
 * second pass writes the encoded output.
 */
static int encode_graphql_field(const char *input, char *output, size_t outlen) {
    if (!input || !output || outlen == 0) return -1;

    size_t i = 0, j = 0;
    size_t input_len = strlen(input);

    /* Ensure we have room for at least the null terminator */
    if (outlen < 2) {
        output[0] = '\0';
        return -1;
    }

    while (i < input_len && j < outlen - 1) {
        unsigned char c = (unsigned char)input[i];

        /* Handle multi-byte UTF-8 sequences - pass through unchanged
         * to preserve internationalization support */
        if (c >= 0x80) {
            /* UTF-8 continuation: determine sequence length */
            int seq_len = 0;
            if ((c & 0xE0) == 0xC0) seq_len = 2;
            else if ((c & 0xF0) == 0xE0) seq_len = 3;
            else if ((c & 0xF8) == 0xF0) seq_len = 4;
            else { i++; continue; } /* invalid UTF-8, skip */

            /* Copy the full UTF-8 sequence */
            if (j + seq_len < outlen) {
                memcpy(output + j, input + i, seq_len);
                j += seq_len;
                i += seq_len;
            } else {
                break; /* not enough room */
            }
            continue;
        }

        /* ASCII range - apply escaping rules */
        switch (c) {
            case '"':
                if (j + 2 <= outlen - 1) {
                    output[j++] = '\\';
                    output[j++] = '"';
                } else goto done;
                break;
            case '\\':
                if (j + 2 <= outlen - 1) {
                    output[j++] = '\\';
                    output[j++] = '\\';
                } else goto done;
                break;
            case '\n':
                if (j + 2 <= outlen - 1) {
                    output[j++] = '\\';
                    output[j++] = 'n';
                } else goto done;
                break;
            case '\r':
                if (j + 2 <= outlen - 1) {
                    output[j++] = '\\';
                    output[j++] = 'r';
                } else goto done;
                break;
            case '\t':
                if (j + 2 <= outlen - 1) {
                    output[j++] = '\\';
                    output[j++] = 't';
                } else goto done;
                break;
            default:
                /* For other control characters, use unicode escape */
                if (c < 0x20) {
                    if (j + 6 <= outlen - 1) {
                        j += snprintf(output + j, outlen - j, "\\u%04x", c);
                    } else goto done;
                } else {
                    output[j++] = c;
                }
                break;
        }
        i++;
    }

done:
    output[j] = '\0';
    return 0;
}

/* Validate that an encoded field doesn't contain unescaped dangerous chars.
 * Returns 0 if safe, -1 if potentially dangerous content detected.
 * This is a defense-in-depth check after encoding. */
static int validate_encoded_field(const char *encoded) {
    if (!encoded) return -1;
    size_t len = strlen(encoded);
    size_t i = 0;

    while (i < len) {
        if (encoded[i] == '\\') {
            /* Skip escaped character */
            i += 2;
            continue;
        }
        /* Check for unescaped control chars - but NOT quotes since
         * the outer JSON layer adds those */
        if ((unsigned char)encoded[i] < 0x20) {
            return -1;
        }
        i++;
    }
    return 0;
}

static int build_email_mutation(const char *to, const char *subject, 
                                const char *body, char *query, size_t qlen) {
    char safe_to[MAX_ENCODED_LEN];
    char safe_subject[MAX_ENCODED_LEN];
    char safe_body[MAX_ENCODED_LEN];

    /* Encode all fields for GraphQL string embedding */
    if (encode_graphql_field(to, safe_to, sizeof(safe_to)) != 0) return -1;
    if (encode_graphql_field(subject, safe_subject, sizeof(safe_subject)) != 0) return -1;
    if (encode_graphql_field(body, safe_body, sizeof(safe_body)) != 0) return -1;

    /* Defense-in-depth validation */
    if (validate_encoded_field(safe_to) != 0) return -1;
    if (validate_encoded_field(safe_subject) != 0) return -1;
    if (validate_encoded_field(safe_body) != 0) return -1;

    snprintf(query, qlen,
        "{\"query\": \"mutation { sendEmail(to: \\\"%s\\\", subject: \\\"%s\\\", body: \\\"%s\\\") { status messageId } }\"}",
        safe_to, safe_subject, safe_body);

    return 0;
}

static int execute_graphql_request(const char *endpoint, const char *query) {
    CURL *curl = curl_easy_init();
    if (!curl) return -1;

    const char *token = getenv("GRAPHQL_AUTH_TOKEN");
    if (!token) {
        curl_easy_cleanup(curl);
        return -1;
    }

    char auth_header[512];
    int written = snprintf(auth_header, sizeof(auth_header), "Authorization: Bearer %s", token);
    if (written < 0 || (size_t)written >= sizeof(auth_header)) {
        curl_easy_cleanup(curl);
        return -1;
    }

    struct curl_slist *headers = NULL;
    headers = curl_slist_append(headers, "Content-Type: application/json");
    headers = curl_slist_append(headers, auth_header);

    response_buf_t resp = {0};

    curl_easy_setopt(curl, CURLOPT_URL, endpoint);
    curl_easy_setopt(curl, CURLOPT_HTTPHEADER, headers);
    curl_easy_setopt(curl, CURLOPT_POSTFIELDS, query);
    curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, write_callback);
    curl_easy_setopt(curl, CURLOPT_WRITEDATA, &resp);
    curl_easy_setopt(curl, CURLOPT_SSL_VERIFYPEER, 1L);
    curl_easy_setopt(curl, CURLOPT_SSL_VERIFYHOST, 2L);
    curl_easy_setopt(curl, CURLOPT_TIMEOUT, 30L);

    CURLcode res = curl_easy_perform(curl);

    int ret = (res == CURLE_OK) ? 0 : -1;

    free(resp.data);
    curl_slist_free_all(headers);
    curl_easy_cleanup(curl);

    return ret;
}

int main(int argc, char *argv[]) {
    if (argc != 5) {
        fprintf(stderr, "Usage: %s <endpoint> <to> <subject> <body>\n", argv[0]);
        return 1;
    }

    const char *endpoint = argv[1];
    const char *to = argv[2];
    const char *subject = argv[3];
    const char *body = argv[4];

    /* Input length validation */
    if (strlen(to) > MAX_FIELD_LEN || strlen(subject) > MAX_FIELD_LEN || 
        strlen(body) > MAX_FIELD_LEN) {
        fprintf(stderr, "Error: field exceeds maximum length\n");
        return 1;
    }

    char query[MAX_QUERY_LEN];
    if (build_email_mutation(to, subject, body, query, sizeof(query)) != 0) {
        fprintf(stderr, "Error: failed to build query\n");
        return 1;
    }

    int retries = 0;
    int result = -1;
    while (retries < MAX_RETRIES && result != 0) {
        result = execute_graphql_request(endpoint, query);
        if (result != 0) retries++;
    }

    return (result == 0) ? 0 : 1;
}
